// Normalizes input and intelligently detects action
const body = $input.first().json.body || $input.first().json;
let action = body.action;

if (!action) {
  if (body.session_id) {
    action = 'start_dating';
  } else if (body.messages && (body.scorer_id || body.target_id)) {
    action = 'score_date';
  } else if (body.profile_a && body.profile_b) {
    action = 'simulate_date';
  } else {
    action = 'analyze_profile';
  }
}

return {
  json: {
    ...body,
    action: action
  }
};

// Groq Multi-Key Failover Engine for Profile Analysis
const input = $input.first().json.body || $input.first().json;

// Hardcoded Direct Groq API Keys with Fallback Rotation
const groqKeys = [];
try {
  if (typeof $env !== 'undefined' && $env?.GROQ_API_KEY) groqKeys.push($env.GROQ_API_KEY);
  if (typeof $env !== 'undefined' && $env?.GROQ_API_KEY_FALLBACK_1) groqKeys.push($env.GROQ_API_KEY_FALLBACK_1);
  if (typeof $env !== 'undefined' && $env?.GROQ_API_KEY_FALLBACK_2) groqKeys.push($env.GROQ_API_KEY_FALLBACK_2);
} catch (e) {}

if (input.groq_api_key) groqKeys.push(input.groq_api_key);
if (Array.isArray(input.groq_fallback_keys)) {
  for (const k of input.groq_fallback_keys) {
    if (k) groqKeys.push(k);
  }
}

const groqModels = ['openai/gpt-oss-120b', 'qwen/qwen3.8-27b', 'openai/gpt-oss-20b', 'llama-3.3-70b-versatile'];
const openAiKey = input.openai_api_key || '';

const personName = input.name || 'Anonymous';
const linkedinUrl = input.linkedin_url || '';
const instagramUrl = input.instagram_url || '';

const systemPrompt = `You are an expert psychological profiler for an agentic dating platform called AgentMatch.
Your task is to analyze a person based on their LinkedIn and Instagram presence and produce their comprehensive AI dating persona.

Respond with a valid JSON object ONLY. No conversational text, no markdown backticks.
{
  "tagline": "Short punchy essence (e.g. Architect by day, backcountry explorer by night)",
  "age_estimate": "Estimated age or 30s",
  "location": "City, Country or State",
  "occupation": "Job title",
  "company": "Company or Independent",
  "education": "School / Degree",
  "needs": ["4 core relationship needs"],
  "hobbies": ["4 active leisure hobbies"],
  "interests": ["4 passions or intellectual pursuits"],
  "values": ["4 guiding principles"],
  "personality": {
    "openness": 0.9,
    "conscientiousness": 0.85,
    "extraversion": 0.75,
    "agreeableness": 0.88,
    "neuroticism": 0.2
  },
  "communication_style": "Conversational description",
  "energy_level": "high",
  "lifestyle": "Daily rhythm and leisure description",
  "love_language": "Primary love language",
  "summary": "3-4 sentences synthesizing what this person's agent seeks in romantic compatibility"
}`;

const userPrompt = `Person Name: ${personName}\nLinkedIn URL: ${linkedinUrl}\nInstagram URL: ${instagramUrl}\nAdditional Notes: ${JSON.stringify(input.raw_data || {})}`;

let profileResult = null;
let usedProvider = 'none';
let errors = [];

const postJson = async (url, headers, payload) => {
  if (typeof fetch === 'function') {
    const res = await fetch(url, {
      method: 'POST',
      headers: headers,
      body: JSON.stringify(payload)
    });
    if (!res.ok) {
      const errText = await res.text();
      throw new Error(`HTTP ${res.status}: ${errText}`);
    }
    return await res.json();
  } else if (typeof this?.helpers?.httpRequest === 'function') {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: url,
      headers: headers,
      body: payload,
      json: true
    });
  } else {
    throw new Error('No HTTP transport available');
  }
};

// Try Groq Keys and Models
keyLoop:
for (let i = 0; i < groqKeys.length; i++) {
  const key = groqKeys[i];
  for (const model of groqModels) {
    try {
      const data = await postJson(
        'https://api.groq.com/openai/v1/chat/completions',
        {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${key}`,
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AgentMatch/1.0'
        },
        {
          model: model,
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
          ],
          temperature: 0.5,
          response_format: { type: 'json_object' }
        }
      );

      if (data && data.choices && data.choices[0] && data.choices[0].message) {
        const content = data.choices[0].message.content;
        profileResult = JSON.parse(content);
        usedProvider = `Groq (Key #${i + 1} - ${model})`;
        break keyLoop;
      }
    } catch (err) {
      errors.push(`Groq Key #${i + 1} (${model}) error: ${err.message}`);
    }
  }
}

// Fallback to OpenAI if provided
if (!profileResult && openAiKey) {
  try {
    const data = await postJson(
      'https://api.openai.com/v1/chat/completions',
      {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${openAiKey}`,
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AgentMatch/1.0'
      },
      {
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt }
        ],
        temperature: 0.5,
        response_format: { type: 'json_object' }
      }
    );
    if (data && data.choices && data.choices[0]) {
      profileResult = JSON.parse(data.choices[0].message.content);
      usedProvider = 'OpenAI (gpt-4o-mini)';
    }
  } catch (err) {
    errors.push(`OpenAI error: ${err.message}`);
  }
}

// Deterministic fallback if external APIs fail
if (!profileResult) {
  profileResult = {
    tagline: `Visionary builder & explorer | ${personName}`,
    age_estimate: '32',
    location: 'San Francisco, CA',
    occupation: 'Innovator & Technologist',
    company: 'Next-Gen Ventures',
    education: 'Top University',
    needs: ['Intellectual companionship', 'Authentic emotional presence', 'Mutual creative drive', 'Healthy life balance'],
    hobbies: ['Morning trail running', 'Landscape photography', 'Specialty coffee brewing', 'Reading non-fiction'],
    interests: ['Artificial intelligence', 'Architecture', 'Sustainable design', 'Global travel'],
    values: ['Integrity', 'Empathy', 'High agency', 'Continuous growth'],
    personality: { openness: 0.92, conscientiousness: 0.88, extraversion: 0.80, agreeableness: 0.86, neuroticism: 0.22 },
    communication_style: 'Warm, articulate, deeply curious, active listener.',
    energy_level: 'high',
    lifestyle: 'Productive morning rituals, creative work blocks, quiet evening walks and culinary hosting.',
    love_language: 'Quality Time & Words of Affirmation',
    summary: `${personName}'s agent seeks a deeply curious, emotionally grounded partner who balances ambition with warmth and spontaneous adventure.`
  };
  usedProvider = 'Deterministic Heuristic Persona Engine';
}

return {
  json: {
    person_id: input.person_id || input.id,
    name: personName,
    profile: profileResult,
    provider_used: usedProvider,
    errors: errors.length > 0 ? errors : undefined,
    timestamp: new Date().toISOString()
  }
};

